-- Keep updated_at correct for every writer, not only Prisma.
CREATE FUNCTION "finora"."set_updated_at"() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = ''
AS $$
BEGIN
  NEW.updated_at := greatest(now(), OLD.updated_at);
  RETURN NEW;
END;
$$;

CREATE TRIGGER "owners_set_updated_at"
  BEFORE UPDATE ON "finora"."owners"
  FOR EACH ROW EXECUTE FUNCTION "finora"."set_updated_at"();
